// ---- palettes -----------------------------------------------------------------------------------------------------
// mix entries are [block, weight] or [block, weight, "full"] (full-block cells only).
export const ROOF_PALETTES = {
  slate: { mix: [["cobbled_deepslate", 45], ["deepslate_tile", 35], ["polished_deepslate", 20]], eave: "tuff_brick", ridge: "stone_brick", verge: "dark_oak" },   // overworld blocks only
  "dark-slate": { mix: [["deepslate_tile", 70], ["cobbled_deepslate", 15], ["polished_blackstone_brick", 10], ["cracked_deepslate_tiles", 5, "full"]], eave: "polished_blackstone_brick", ridge: "polished_deepslate", verge
  "spruce-shingle": { mix: [["spruce", 60], ["dark_oak", 25], ["mangrove", 15]], eave: "dark_oak", ridge: "dark_oak", verge: "birch" },
  "red-tile": { mix: [["brick", 55], ["granite", 25], ["polished_granite", 10], ["mangrove", 10]], eave: "mud_brick", ridge: "mud_brick", verge: "smooth_quartz" },
  "barn-red": { mix: [["mangrove", 55], ["brick", 25], ["dark_oak", 20]], eave: "dark_oak", ridge: "dark_oak", verge: "smooth_quartz" },
  copper: { mix: [["weathered_cut_copper", 50], ["oxidized_cut_copper", 50]], rows: true, gradient: "none", eave: "exposed_cut_copper", ridge: "cut_copper" },
  "dark-glazed": { mix: [["deepslate_tile", 50], ["cobbled_deepslate", 30], ["polished_blackstone_brick", 20]], eave: "polished_blackstone_brick", ridge: "smooth_quartz", verge: "dark_oak" },
  // cut_sandstone has a slab but no stairs: full-block cells only. The eave/ridge are the light coping (smooth_quartz).
  "sandstone-deck": { mix: [["smooth_sandstone", 70], ["cut_sandstone", 20, "full"], ["sandstone", 10]], eave: "smooth_quartz", ridge: "smooth_quartz", soffit: "spruce", gradient: "none" },
};

// ---- deterministic hash ---------------------------------------------------------------------------------------------
function hash(x, z, c, seed, salt = 0) {
  let h = (Math.imul(x | 0, 0x9e3779b1) ^ Math.imul(z | 0, 0x85ebca6b) ^ Math.imul(c | 0, 0xc2b2ae35) ^ Math.imul((seed | 0) + 0x1234567, 0x27d4eb2f) ^ Math.imul(salt + 1, 0x165667b1)) >>> 0;
  h ^= h >>> 15; h = Math.imul(h, 0x2c1b3c6d) >>> 0; h ^= h >>> 12; h = Math.imul(h, 0x297a2d39) >>> 0; h ^= h >>> 15;
  return (h >>> 0) / 4294967296;
}
